        var perfConnection=new SqlConnectionStringBuilder(target.ConnectionString){ApplicationName="fc2discovery-performance",MinPoolSize=8,MaxPoolSize=8}.ConnectionString;var perfReader=new SqlSecurityAuthority(perfConnection,target.InstallationId);var leases=await Task.WhenAll(Enumerable.Range(0,8).Select(async _=>{var lease=new SqlConnection(perfConnection);await lease.OpenAsync();return lease;}));foreach(var lease in leases)await lease.DisposeAsync();await perfReader.ReadCommissioningSiteAsync(holdToken,site);var scenarios=new List<object>();
        foreach(var concurrency in new[]{1,8})
